import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"FAQ & troubleshooting","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1787084764000}`),a={name:`guide/faq.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="faq-troubleshooting" tabindex="-1">FAQ &amp; troubleshooting <a class="header-anchor" href="#faq-troubleshooting" aria-label="Permalink to “FAQ &amp; troubleshooting”">​</a></h1><h2 id="every-call-fails-with-missing-required-environment-variable-s" tabindex="-1">Every call fails with &quot;missing required environment variable(s)&quot; <a class="header-anchor" href="#every-call-fails-with-missing-required-environment-variable-s" aria-label="Permalink to “Every call fails with &quot;missing required environment variable(s)&quot;”">​</a></h2><p>The server started without <code>MEALIE_URL</code> and/or <code>MEALIE_API_TOKEN</code>. That is deliberate — the server completes the MCP handshake and lists its tools without credentials so it can be introspected — but no call can succeed. Set both variables in the client config; see <a href="/guide/clients">Connecting clients</a>.</p><h2 id="i-set-mealie-read-only-1-and-the-write-tools-are-still-there" tabindex="-1">I set <code>MEALIE_READ_ONLY=1</code> and the write tools are still there <a class="header-anchor" href="#i-set-mealie-read-only-1-and-the-write-tools-are-still-there" aria-label="Permalink to “I set MEALIE_READ_ONLY=1 and the write tools are still there”">​</a></h2><p>The two boolean variables compare against the literal string <code>true</code>, so <code>1</code>, <code>yes</code> and <code>True</code> all leave them <strong>off</strong>. A typo fails off, never on. The startup line on stderr reports the mode actually in effect — check it after changing the config.</p><h2 id="a-write-tool-fails-with-403" tabindex="-1">A write tool fails with 403 <a class="header-anchor" href="#a-write-tool-fails-with-403" aria-label="Permalink to “A write tool fails with 403”">​</a></h2><p>The token acts as the user who created it, with that user&#39;s permission flags. Call <code>get_about</code>: it reports the identity behind the token and the three flags that gate the write tools in practice (<code>canOrganize</code>, <code>canManage</code>, <code>canInvite</code>). Organizer, food and unit management needs <code>canOrganize</code>.</p><h2 id="suggest-recipes-returns-nothing" tabindex="-1"><code>suggest_recipes</code> returns nothing <a class="header-anchor" href="#suggest-recipes-returns-nothing" aria-label="Permalink to “suggest_recipes returns nothing”">​</a></h2><p>That tool ranks recipes by the foods and tools marked &quot;on hand&quot; in Mealie, so it only produces anything on an instance that maintains structured foods, units and an on-hand pantry. On a collection of plain-text ingredients it returns nothing — use <code>search_recipes</code> there. Likewise, <code>list_foods</code> and <code>list_units</code> being empty means the instance never seeded them, not a failure.</p><h2 id="import-recipe-from-url-refuses-my-url" tabindex="-1"><code>import_recipe_from_url</code> refuses my URL <a class="header-anchor" href="#import-recipe-from-url-refuses-my-url" aria-label="Permalink to “import_recipe_from_url refuses my URL”">​</a></h2><p>URLs handed to the import tools must be public <code>http</code>/<code>https</code> addresses. Loopback, private-range and link-local addresses and <code>.lan</code>/<code>.internal</code>/<code>.local</code> hosts are refused, because Mealie fetches the URL from inside its own network — see <a href="/guide/security#untrusted-content">Security</a>. If the page needs a login, or Mealie cannot parse it, fetch the HTML yourself and use <code>import_recipe_from_html_or_json</code>.</p><h2 id="import-recipe-from-image-fails" tabindex="-1"><code>import_recipe_from_image</code> fails <a class="header-anchor" href="#import-recipe-from-image-fails" aria-label="Permalink to “import_recipe_from_image fails”">​</a></h2><p>That tool has Mealie run the photo through its configured AI provider. Without one the call fails — and the setting itself is only visible to a group manager or admin in Mealie&#39;s UI.</p><h2 id="an-import-came-out-empty-or-garbled" tabindex="-1">An import came out empty or garbled <a class="header-anchor" href="#an-import-came-out-empty-or-garbled" aria-label="Permalink to “An import came out empty or garbled”">​</a></h2><p>Run <code>preview_recipe_url</code> first: it fetches the page and reports what Mealie would extract, without saving anything. If the preview is already empty, the page&#39;s markup is the problem, not the import.</p><h2 id="a-delete-tool-answered-with-a-token-instead-of-deleting" tabindex="-1">A delete tool answered with a token instead of deleting <a class="header-anchor" href="#a-delete-tool-answered-with-a-token-instead-of-deleting" aria-label="Permalink to “A delete tool answered with a token instead of deleting”">​</a></h2><p>That is the <a href="/guide/security#confirmation-tokens">confirmation flow</a>: the first call describes what is about to happen and returns a single-use token, the second call — same arguments plus <code>confirm_token</code> — performs it. Tokens expire after a few minutes and are bound to the specific target.</p><h2 id="why-is-there-no-bulk-export-backup-user-management-tool" tabindex="-1">Why is there no bulk export / backup / user management tool? <a class="header-anchor" href="#why-is-there-no-bulk-export-backup-user-management-tool" aria-label="Permalink to “Why is there no bulk export / backup / user management tool?”">​</a></h2><p>By design. The point of the server is a curated surface; the <a href="/guide/security#not-exposed-on-purpose">list of deliberately unexposed routes</a> explains what is missing and why.</p><h2 id="self-signed-certificate-errors" tabindex="-1">Self-signed certificate errors <a class="header-anchor" href="#self-signed-certificate-errors" aria-label="Permalink to “Self-signed certificate errors”">​</a></h2><p>Set <code>MEALIE_INSECURE_TLS=true</code> (exactly <code>true</code>). It disables certificate verification for the Mealie connection only, not for the whole process. Prefer a real certificate where you can.</p><h2 id="where-do-i-report-a-bug-or-ask-a-question" tabindex="-1">Where do I report a bug or ask a question? <a class="header-anchor" href="#where-do-i-report-a-bug-or-ask-a-question" aria-label="Permalink to “Where do I report a bug or ask a question?”">​</a></h2><ul><li>Questions and ideas → <a href="https://github.com/ni-c/mealie-mcp/discussions" target="_blank" rel="noreferrer">Discussions</a></li><li>Reproducible problems → <a href="https://github.com/ni-c/mealie-mcp/issues" target="_blank" rel="noreferrer">Issues</a></li><li>Vulnerabilities → <a href="https://github.com/ni-c/mealie-mcp/security/advisories/new" target="_blank" rel="noreferrer">private reporting</a>, never a public issue</li></ul>`,23)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};